BEGIN;
CREATE TEMP TABLE compat_scope(pa uuid,pb uuid,a uuid);
DO $s$ DECLARE pa uuid:=gen_random_uuid();pb uuid:=gen_random_uuid();a uuid;b uuid;BEGIN
 PERFORM set_config('request.jwt.claims','{}',true);
 SELECT id INTO a FROM auth.users WHERE email LIKE 'pf-parity-%-admin@pharmflow.test' AND coalesce(raw_app_meta_data->>'pharmflow_must_change_password','false')<>'true' LIMIT 1;
 SELECT id INTO b FROM auth.users WHERE email LIKE 'pf-parity-%-other@pharmflow.test' LIMIT 1;
 IF a IS NULL OR b IS NULL THEN RAISE EXCEPTION 'QA identities missing';END IF;
 INSERT INTO public.pharmacies(id,name,code,active,status) VALUES(pa,'Disposable A','QA'||left(pa::text,8),true,'active'),(pb,'Disposable B','QA'||left(pb::text,8),true,'active');
 INSERT INTO public.pharmacy_members(pharmacy_id,user_id,role,active) VALUES(pa,a,'admin',true),(pb,b,'admin',true);
 UPDATE public.pharmflow_pharmacy_permissions_v1 SET receiving='FULL',expiry='FULL',data_access='PHARMACY_ONLY' WHERE pharmacy_id IN(pa,pb);
 INSERT INTO compat_scope VALUES(pa,pb,a);
END $s$;
DO $g$ DECLARE pa uuid;pb uuid;a uuid;BEGIN
 SELECT t.pa,t.pb,t.a INTO pa,pb,a FROM compat_scope t;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 UPDATE public.pharmflow_pharmacy_permissions_v1 SET receiving='DISABLED' WHERE pharmacy_id=pa;
