CREATE FUNCTION pg_temp.compat_fault() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'QA_ROLLBACK';END $$;
DO $ops$ DECLARE pa uuid;a uuid;oid uuid;r record;r2 record;h uuid;v jsonb;n integer;BEGIN
 SELECT t.pa,t.a INTO pa,a FROM compat_scope t;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 INSERT INTO public.pharmflow_active_order_manifest_v1(pharmacy_id,manifest) VALUES(pa,'{"orderData":[],"orderFiles":[]}'::jsonb);
 SELECT manifest INTO v FROM public.get_pharmflow_active_order_manifest(pa);IF v->'orderData'<>'[]'::jsonb THEN RAISE EXCEPTION 'Manifest mismatch';END IF;
 PERFORM public.append_pharmflow_cloud_transaction(pa,'QA-TX','QA-RESET','QAITEM','QA','QABAR',1,'QA','QA',now(),'{}'::jsonb);
 PERFORM public.append_pharmflow_cloud_transaction(pa,'QA-TX','QA-RESET','QAITEM','QA','QABAR',1,'QA','QA',now(),'{}'::jsonb);
 IF (SELECT count(*) FROM public.pharmflow_receiving_transactions_v1 WHERE pharmacy_id=pa AND transaction_id='QA-TX')<>1 THEN RAISE EXCEPTION 'Receipt duplicate';END IF;
 PERFORM public.register_pharmflow_order_upload(pa,'QA-FINAL',current_date,'QA','QA','QA',0);PERFORM public.finalize_pharmflow_order(pa,'QA-FINAL');
 IF NOT EXISTS(SELECT 1 FROM public.pharmflow_orders WHERE pharmacy_id=pa AND order_number='QA-FINAL' AND status='received' AND received_by=a) THEN RAISE EXCEPTION 'Finalize failed';END IF;
 BEGIN PERFORM public.finalize_pharmflow_order(pa,'QA-FINAL');RAISE EXCEPTION 'Double finalize';EXCEPTION WHEN raise_exception THEN IF SQLERRM='Double finalize' THEN RAISE;END IF;END;
 PERFORM public.register_pharmflow_order_upload(pa,'QA-HISTORY',current_date,'QA','QA','QA',1);
 SELECT * INTO r FROM public.finalize_pharmflow_receiving_workspace_v1(pa,'QA-COMP',ARRAY['QA-HISTORY'],'[]'::jsonb,'[{"order_number":"QA-HISTORY","item_code":"QAITEM","item_name":"QA","ordered_qty":1}]'::jsonb);
 SELECT * INTO r2 FROM public.finalize_pharmflow_receiving_workspace_v1(pa,'QA-COMP',ARRAY['QA-HISTORY'],'[]'::jsonb,'[]'::jsonb);
 IF r.workspace_history_id<>r2.workspace_history_id OR r.new_item_count<>1 THEN RAISE EXCEPTION 'Completion retry failed';END IF;h:=r.workspace_history_id;
 SELECT count(*) INTO n FROM public.get_pharmflow_receiving_workspace_history_v1(pa,h);IF n<>1 THEN RAISE EXCEPTION 'History read failed';END IF;
 SELECT count(*) INTO n FROM public.list_pharmflow_new_item_history_v1(pa,current_date,current_date);IF n<>1 THEN RAISE EXCEPTION 'New item history failed';END IF;
 oid:=public.register_pharmflow_order_upload(pa,'QA-DELETE',current_date,'QA','QA','QA',1);
 INSERT INTO public.pharmflow_order_source_items(pharmacy_id,order_id,order_number,line_no,item_code,ordered_qty) VALUES(pa,oid,'QA-DELETE',1,'QAITEM',1);
 INSERT INTO public.pharmflow_finalized_archives_v1(pharmacy_id,archive_id,order_numbers) VALUES(pa,'QA-ARCHIVE',ARRAY['QA-DELETE']);
 BEGIN PERFORM public.delete_pharmflow_order_complete(pa,'QA-DELETE','WRONG');RAISE EXCEPTION 'Confirmation bypass';EXCEPTION WHEN raise_exception THEN IF SQLERRM='Confirmation bypass' THEN RAISE;END IF;END;
 IF NOT EXISTS(SELECT 1 FROM public.pharmflow_orders WHERE id=oid) THEN RAISE EXCEPTION 'Rejected delete wrote';END IF;
 PERFORM public.delete_pharmflow_order_complete(pa,'QA-DELETE','QA-DELETE');
 IF EXISTS(SELECT 1 FROM public.pharmflow_orders WHERE id=oid) OR EXISTS(SELECT 1 FROM public.pharmflow_order_source_items WHERE order_id=oid) OR EXISTS(SELECT 1 FROM public.pharmflow_finalized_archives_v1 WHERE pharmacy_id=pa) THEN RAISE EXCEPTION 'Delete mismatch';END IF;
 oid:=public.register_pharmflow_order_upload(pa,'QA-RESET',current_date,'QA','QA','QA',1);
 INSERT INTO public.pharmflow_order_source_items(pharmacy_id,order_id,order_number,line_no,item_code,ordered_qty) VALUES(pa,oid,'QA-RESET',1,'QAITEM',1);
 INSERT INTO public.pharmflow_cloud_workspaces(pharmacy_id,workspace) VALUES(pa,'{}'::jsonb);
 CREATE TRIGGER compat_fault BEFORE DELETE ON public.pharmflow_cloud_workspaces FOR EACH ROW EXECUTE FUNCTION pg_temp.compat_fault();
 BEGIN PERFORM public.atomic_reset_pharmflow_current_workspace_v4(pa,'RESET CURRENT WORKSPACE');RAISE EXCEPTION 'Fault missing';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'QA_ROLLBACK' THEN RAISE;END IF;END;
